-- Catalog tables + notification prefs. Seeded from src/data/*.ts.
alter table public.profiles add column if not exists notification_prefs jsonb not null default '{"renewals":true,"readiness":true,"utilization":true,"reviews":true}'::jsonb;

create table if not exists public.issuers (
  id text primary key,
  name text not null,
  accent_color text not null,
  application_rules jsonb not null default '[]'::jsonb,
  contact jsonb not null
);
create table if not exists public.transfer_partners (
  id text primary key,
  name text not null,
  type text not null,
  transfers_from jsonb not null default '[]'::jsonb
);
create table if not exists public.cards (
  id text primary key,
  issuer_id text not null references public.issuers (id),
  name text not null,
  annual_fee integer not null,
  product jsonb not null
);
alter table public.issuers enable row level security;
alter table public.transfer_partners enable row level security;
alter table public.cards enable row level security;
drop policy if exists issuers_select_public on public.issuers;
create policy issuers_select_public on public.issuers for select to anon, authenticated using (true);
grant select on table public.issuers to anon, authenticated;
revoke insert, update, delete on table public.issuers from anon, authenticated;
drop policy if exists transfer_partners_select_public on public.transfer_partners;
create policy transfer_partners_select_public on public.transfer_partners for select to anon, authenticated using (true);
grant select on table public.transfer_partners to anon, authenticated;
revoke insert, update, delete on table public.transfer_partners from anon, authenticated;
drop policy if exists cards_select_public on public.cards;
create policy cards_select_public on public.cards for select to anon, authenticated using (true);
grant select on table public.cards to anon, authenticated;
revoke insert, update, delete on table public.cards from anon, authenticated;
on conflict (id) do update set name = excluded.name, accent_color = excluded.accent_color, application_rules = excluded.application_rules, contact = excluded.contact;
on conflict (id) do update set name = excluded.name, type = excluded.type, transfers_from = excluded.transfers_from;
on conflict (id) do update set issuer_id = excluded.issuer_id, name = excluded.name, annual_fee = excluded.annual_fee, product = excluded.product;
